CREATE TABLE app_users (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE documents (id BIGSERIAL PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(255) NOT NULL, checksum VARCHAR(64) NOT NULL, size_bytes BIGINT NOT NULL, extracted_text TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_doc_owner_created ON documents(owner_id, created_at DESC); CREATE INDEX idx_doc_checksum_owner ON documents(checksum, owner_id);
CREATE TABLE collections (id BIGSERIAL PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, name VARCHAR(120) NOT NULL, description VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE search_history (id BIGSERIAL PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, query VARCHAR(500) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
